/* ---------- khoá cuộn + menu di động ---------- */
var lastFocus=null;
function lock(v){body.classList.toggle('lock',v);root.style.overflow=v?'hidden':''}
var mnav=$('#mnav'),mb=$('#menuBtn');
function menu(open){if(!mnav)return;mnav.classList.toggle('open',open);mb.setAttribute('aria-expanded',open);lock(open);if(open){lastFocus=doc.activeElement;setTimeout(function(){$('#menuClose').focus()},60)}else if(lastFocus){lastFocus.focus()}}
