$$('#mnav a').forEach(function(a){on(a,'click',function(){mnav.classList.remove('open');mb.setAttribute('aria-expanded','false');lock(false)})});
function trap(box,e){if(e.key!=='Tab')return;var f=$$('a[href],button:not([disabled]),input,select,textarea',box).filter(function(x){return x.offsetParent!==null});if(!f.length)return;var a=f[0],z=f[f.length-1];if(e.shiftKey&&doc.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&doc.activeElement===z){e.preventDefault();a.focus()}}
