/* ---------- tìm kiếm trong site ---------- */
var srch=$('#srch'),sq=$('#srchQ'),sres=$('#srchRes');
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d')}
function hl(t,q){if(!q)return esc(t);var nt=norm(t),i=nt.indexOf(q);if(i<0)return esc(t);return esc(t.slice(0,i))+'<mark>'+esc(t.slice(i,i+q.length))+'</mark>'+esc(t.slice(i+q.length))}
function runSearch(){var q=norm(sq.value.trim());
 if(!q){sres.innerHTML='<div class="srch-hint">Gợi ý tìm nhanh:<br>'+['villa hồ bơi','tiệc cưới','spa','trẻ em','sân bay','ưu đãi','bữa sáng'].map(function(x){return '<button class="chip" type="button" data-q="'+x+'">'+x+'</button>'}).join('')+'</div>';return}
 var words=q.split(/\s+/),res=D.search.filter(function(it){var h=norm(it.t+' '+it.d+' '+it.k);return words.every(function(w){return h.indexOf(w)>-1})}).slice(0,12);
 sres.innerHTML=res.length?res.map(function(it){return '<a href="'+PRE+it.u+'"><span class="tag">'+esc(it.k)+'</span><b>'+hl(it.t,q)+'</b><small>'+hl(it.d,q)+'</small></a>'}).join(''):'<div class="srch-hint">Chưa thấy kết quả cho “'+esc(sq.value)+'”. Thử từ khác, hoặc gọi <a href="tel:0900000000">0900 000 000</a>.</div>'}
function openSearch(v){if(!srch)return;lastFocus=doc.activeElement;srch.classList.add('open');lock(true);runSearch();setTimeout(function(){sq.focus()},50)}
function closeSearch(){srch.classList.remove('open');lock(false);if(lastFocus)lastFocus.focus()}
on($('#srchBtn'),'click',openSearch);on($('#srchClose'),'click',closeSearch);
on(sq,'input',runSearch);
on(srch,'click',function(e){if(e.target===srch)closeSearch();var b=e.target.closest('[data-q]');if(b){sq.value=b.getAttribute('data-q');runSearch();sq.focus()}});
on(srch,'keydown',function(e){trap(srch,e)});
on(doc,'keydown',function(e){
 if(e.key==='Escape'){if(srch&&srch.classList.contains('open'))closeSearch();else if(mnav&&mnav.classList.contains('open'))menu(false);else if(lbEl&&lbEl.classList.contains('open'))lbClose();else closePops()}
 if((e.key==='/'||(e.key==='k'&&(e.metaKey||e.ctrlKey)))&&!/INPUT|TEXTAREA|SELECT/.test((doc.activeElement||{}).tagName||'')){e.preventDefault();openSearch()}
});

