/* ---------- yêu thích ---------- */
function favs(){return get('fav',[])}
function favCount(){var n=favs().length;$$('[data-fav-n]').forEach(function(el){el.textContent=n;el.hidden=!n})}
function favToggle(id){var f=favs(),i=f.indexOf(id);if(i>-1)f.splice(i,1);else f.push(id);put('fav',f);favCount();var r=room(id);toast(i>-1?'Đã bỏ “'+r.name+'” khỏi danh sách lưu':'Đã lưu “'+r.name+'”. Xem lại ở biểu tượng trái tim.');return i<0}
function bindFav(scope){$$('[data-fav]',scope).forEach(function(b){var id=b.getAttribute('data-fav');b.setAttribute('aria-pressed',favs().indexOf(id)>-1);if(b._f)return;b._f=1;on(b,'click',function(){var v=favToggle(id);$$('[data-fav="'+id+'"]').forEach(function(x){x.setAttribute('aria-pressed',v)});if(PG==='rooms'&&roomsApply)roomsApply()})})}
favCount();bindFav();

/* ---------- hộp ảnh ---------- */
var lbEl=$('#lb'),lbList=[],lbI=0;
function lbShow(){var it=lbList[lbI];$('#lbImg').src=it.src.replace(/w=\d+/,'w=1800');$('#lbImg').alt=it.cap;$('#lbCap').textContent=it.cap;$('#lbCount').textContent=(lbI+1)+' / '+lbList.length}
function lbOpen(list,i){lbList=list;lbI=i;lastFocus=doc.activeElement;lbShow();lbEl.classList.add('open');lock(true);setTimeout(function(){$('#lbClose').focus()},50)}
function lbClose(){lbEl.classList.remove('open');lock(false);if(lastFocus)lastFocus.focus()}
function lbStep(k){lbI=(lbI+k+lbList.length)%lbList.length;lbShow()}
on($('#lbClose'),'click',lbClose);on($('#lbPrev'),'click',function(){lbStep(-1)});on($('#lbNext'),'click',function(){lbStep(1)});
on(lbEl,'keydown',function(e){if(e.key==='ArrowLeft')lbStep(-1);if(e.key==='ArrowRight')lbStep(1);trap(lbEl,e)});
