var tx=null;on(lbEl,'touchstart',function(e){tx=e.touches[0].clientX},{passive:true});on(lbEl,'touchend',function(e){if(tx===null)return;var dx=e.changedTouches[0].clientX-tx;if(Math.abs(dx)>50)lbStep(dx<0?1:-1);tx=null});
function lbBind(btns){btns.forEach(function(b,i){on(b,'click',function(){var vis=btns.filter(function(x){return !x.hidden&&x.offsetParent!==null});lbOpen(vis.map(function(x){var im=$('img',x);return {src:im.currentSrc||im.src,cap:x.getAttribute('data-cap')||im.alt}}),Math.max(0,vis.indexOf(b)))})})}

/* ---------- kiểm tra form ---------- */
function errOf(el){var w=el.closest('.fld,.consent,[data-errwrap]');if(!w)return null;var e=$('.err',w);if(!e){e=doc.createElement('p');e.className='err';w.appendChild(e)}if(!e.id){e.id=(el.id||el.name||'f')+'-err'}var d=el.getAttribute('aria-describedby')||'';if(d.indexOf(e.id)<0)el.setAttribute('aria-describedby',(d+' '+e.id).trim());return e}
function vField(el){
 var msg='',v=el.type==='checkbox'?el.checked:String(el.value||'').trim(),lbl=el.getAttribute('data-lbl')||'thông tin này';
 if(el.type==='checkbox'){if(el.required&&!v)msg='Vui lòng tick ô đồng ý để chúng tôi xử lý yêu cầu.'}
 else if(el.required&&!v)msg=(el.tagName==='SELECT'?'Vui lòng chọn ':'Vui lòng nhập ')+lbl+'.';
 else if(v&&el.getAttribute('data-v')==='phone'&&!/^(0|\+84)\d{9}$/.test(v.replace(/[\s.\-]/g,'')))msg='Số điện thoại chưa đúng, ví dụ 0900 000 000.';
 else if(v&&el.getAttribute('data-v')==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v))msg='Email chưa đúng định dạng, ví dụ ten@email.com.';
 else if(v&&el.getAttribute('data-v')==='name'&&v.replace(/\s+/g,' ').length<4)msg='Họ tên cần ít nhất 4 ký tự.';
 el.setAttribute('aria-invalid',msg?'true':'false');var e=errOf(el);if(e)e.textContent=msg;return !msg}
function vForm(f){var ok=true,first=null;$$('input,select,textarea',f).forEach(function(el){if(el.closest('[hidden]')||el.type==='hidden')return;if(!(el.required||el.getAttribute('data-v')))return;if(!vField(el)){ok=false;first=first||el}});if(first)first.focus();return ok}
function liveV(f){$$('input,select,textarea',f).forEach(function(el){on(el,'blur',function(){if(el.value||el.getAttribute('aria-invalid'))vField(el)});on(el,el.type==='checkbox'||el.tagName==='SELECT'?'change':'input',function(){if(el.getAttribute('aria-invalid')==='true')vField(el)})})}
function mkCode(p){var c='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',s='';for(var i=0;i<6;i++)s+=c[Math.floor(Math.random()*c.length)];return p+'-'+s}
function optText(el){return el.tagName==='SELECT'?el.options[el.selectedIndex].text:el.value}
/* form minh hoạ chung: data-form="TIỀN TỐ" */
$$('form[data-form]').forEach(function(f){liveV(f);on(f,'submit',function(e){e.preventDefault();if(f._pre&&!f._pre())return;if(!vForm(f))return;
 var done=doc.getElementById(f.getAttribute('data-done')),code=mkCode(f.getAttribute('data-form'));
 if(done){$$('[data-code]',done).forEach(function(x){x.textContent=code});var ul=$('[data-sumlist]',done);if(ul){ul.innerHTML=$$('[data-sum]',f).filter(function(x){return x.value&&!x.closest('[hidden]')}).map(function(x){return '<li><b>'+x.getAttribute('data-sum')+':</b> '+esc(optText(x))+'</li>'}).join('')+(f._extra?f._extra():'')}
  f.hidden=true;done.hidden=false;done.setAttribute('tabindex','-1');done.focus();done.scrollIntoView({block:'center',behavior:RM?'auto':'smooth'})}
});var again=doc.getElementById(f.getAttribute('data-done'));if(again)$$('[data-again]',again).forEach(function(b){on(b,'click',function(){f.reset();f.hidden=false;again.hidden=true;if(f._reset)f._reset();$$('[aria-invalid]',f).forEach(function(x){x.removeAttribute('aria-invalid')});$$('.err',f).forEach(function(x){x.textContent=''})})})});

/* bước +/- */
function stepper(el,min,max,val,cb){el.innerHTML='<button type="button" aria-label="Giảm">'+icon('minus','ic ic-s')+'</button><output aria-live="polite">'+val+'</output><button type="button" aria-label="Tăng">'+icon('plus','ic ic-s')+'</button>';var b=$$('button',el),o=$('output',el);
 function set(v){val=Math.max(min,Math.min(max,v));o.textContent=val;b[0].disabled=val<=min;b[1].disabled=val>=max;cb&&cb(val)}
 on(b[0],'click',function(){set(val-1)});on(b[1],'click',function(){set(val+1)});b[0].disabled=val<=min;b[1].disabled=val>=max;return {set:set,get:function(){return val}}}

/* ---------- lịch chọn ngày ---------- */
function Cal(el,o){
 o=o||{};var st=o.start?parse(o.start):null,en=o.end?parse(o.end):null,r=o.room?room(o.room):null,t0=today(),mx=addD(t0,365),nM=o.months||2;
 var view=new Date((st||t0).getFullYear(),(st||t0).getMonth(),1);
 function isS(d){return r&&sold(r,d)}
 function render(){
  var h='<div class="cal-top"><button type="button" class="ic-btn" data-cv="-1" aria-label="Tháng trước"'+(view<=new Date(t0.getFullYear(),t0.getMonth(),1)?' disabled':'')+'>'+icon('back')+'</button><span class="small" aria-live="polite">'+(st&&en?'<b class="num">'+diff(st,en)+'&nbsp;đêm</b> · '+fmt(st)+' – '+fmt(en):st?'Chọn ngày trả phòng':'Chọn ngày nhận phòng')+'</span><button type="button" class="ic-btn" data-cv="1" aria-label="Tháng sau">'+icon('go')+'</button></div><div class="cal-months">';
  for(var m=0;m<nM;m++){var md=new Date(view.getFullYear(),view.getMonth()+m,1);
   h+='<div class="cal-m"><h4>Tháng&nbsp;'+(md.getMonth()+1)+', '+md.getFullYear()+'</h4><div class="cal-g">'+['T2','T3','T4','T5','T6','T7','CN'].map(function(x){return '<span class="dow">'+x+'</span>'}).join('');
   for(var i=0,off=(md.getDay()+6)%7;i<off;i++)h+='<span></span>';
   var dim=new Date(md.getFullYear(),md.getMonth()+1,0).getDate();
   for(var dd=1;dd<=dim;dd++){var d=new Date(md.getFullYear(),md.getMonth(),dd),dis=d<t0||d>mx,so=!dis&&isS(d),isSt=st&&+d===+st,isEn=en&&+d===+en,c='cal-d';
    if(so)c+=' sold';if(+d===+t0)c+=' today';if(isSt)c+=' s';if(isEn)c+=' e';if(st&&en&&d>st&&d<en)c+=' rng';
    h+='<button type="button" class="'+c+'" data-d="'+iso(d)+'"'+(dis?' disabled':'')+' aria-pressed="'+!!(isSt||isEn)+'" aria-label="'+fmtL(d)+(so?', hết phòng':'')+'">'+dd+(o.price&&r&&!dis&&!so?'<small>'+shortM(night(r,d))+'</small>':'')+'</button>'}
   h+='</div></div>'}
  h+='</div><div class="cal-leg"><span><i class="k-s"></i>Ngày nhận, trả</span><span><i></i>Trong kỳ ở</span>'+(r?'<span><i class="k-x"></i>Hết phòng</span>':'')+'<span><i class="k-t"></i>Hôm nay</span>'+(o.price&&r?'<span>Số nhỏ: giá một đêm (triệu đồng)</span>':'')+'</div>';
  el.innerHTML=h}
 on(el,'click',function(e){var b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.hasAttribute('data-cv')){view=new Date(view.getFullYear(),view.getMonth()+(+b.getAttribute('data-cv')),1);render();var nb=$('[data-cv="'+b.getAttribute('data-cv')+'"]',el);if(nb&&!nb.disabled)nb.focus();return}
  var d=parse(b.getAttribute('data-d')),so=b.classList.contains('sold');
  if(!st||en||d<=st){if(so){toast('Đêm '+fmt(d)+' đã hết hạng phòng này, vui lòng chọn ngày khác.');return}st=d;en=null}
  else{for(var x=st;x<d;x=addD(x,1))if(r&&sold(r,x)){toast('Trong khoảng này có đêm đã hết phòng. Hãy chọn lại ngày nhận phòng.');st=so?null:d;en=null;render();o.onChange&&o.onChange(st,en);return}
   if(diff(st,d)>30){toast('Đặt trực tuyến tối đa 30 đêm, ở dài hơn vui lòng gọi 0900 000 000.');return}en=d}
  render();var f=$('[data-d="'+b.getAttribute('data-d')+'"]',el);if(f)f.focus();o.onChange&&o.onChange(st,en)});
 render();
 return {set:function(a,b,rid){st=a?parse(a):null;en=b?parse(b):null;if(rid!==undefined)r=rid?room(rid):null;if(st)view=new Date(st.getFullYear(),st.getMonth(),1);render()},get:function(){return [st,en]}};
}
