/* tổng tiền (dùng ở chi tiết phòng + đặt phòng) */
function sumHTML(q,s){if(!q)return '<p class="small">Chọn ngày và hạng phòng để xem tạm tính.</p>';
 var h='<div class="sum"><div><span>'+moneyH(Math.round(q.sum/q.n/1000)*1000)+' × '+q.n+'&nbsp;đêm <span class="sub">(trung bình)</span></span><span>'+moneyH(q.sum)+'</span></div>';
 q.exl.forEach(function(x){h+='<div><span>'+esc(x.e.name)+' × '+x.q+(x.e.per_night?' × '+q.n+'&nbsp;đêm':'')+'</span><span>'+moneyH(x.v)+'</span></div>'});
 if(q.dis)h+='<div class="dis"><span>Mã '+esc(q.pr.p.code)+'</span><span>−'+moneyH(q.dis)+'</span></div>';
 h+='<div class="tot"><span>Tổng cộng</span><b>'+moneyH(q.tot)+'</b></div><div class="sub"><span>Đã gồm phí phục vụ 5%</span><span>'+moneyH(q.svc)+'</span></div><div class="sub"><span>Đã gồm VAT 8%</span><span>'+moneyH(q.vat)+'</span></div></div>';
 return h}

